package dev.matchlab; import static org.junit.jupiter.api.Assertions.*; import java.util.*; import org.junit.jupiter.api.Test;
class TelemetryAnalyzerTest {@Test void calculatesFaults(){var r=new TelemetryAnalyzer().analyze(List.of(new TelemetryAnalyzer.Sample(0,0,0,1,0,.9,.2,1,false),new TelemetryAnalyzer.Sample(20,1,0,1,0,.8,.1,1,false)));assertEquals(2,r.samples());assertEquals(Math.sqrt(.5),r.rmsPathError(),1e-9);assertTrue(r.faults().stream().anyMatch(f->f.rule().equals("motor-imbalance")));assertEquals(0,r.reliability());}@Test void healthyRunHasNoFault(){var r=new TelemetryAnalyzer().analyze(List.of(new TelemetryAnalyzer.Sample(0,0,0,0,0,.5,.5,1,true)));assertTrue(r.faults().isEmpty());}}
